// game.js – simple endless runner based on IDEA.md

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) {
    console.error('Canvas with id "game" not found');
    return;
  }
  const ctx = canvas.getContext('2d');
  const WIDTH = canvas.width = canvas.clientWidth || 800;
  const HEIGHT = canvas.height = canvas.clientHeight || 400;

  // ----- constants -----
  const GRAVITY = 0.6;
  const JUMP_VELOCITY = -12;
  const PLAYER_SIZE = 40;
  const GROUND_Y = HEIGHT - 80;
  const OBSTACLE_SPEED = 5;
  const OBSTACLE_FREQ = 1500; // ms
  const SLIDE_TIME = 500; // ms

  // ----- game state -----
  let score = 0;
  let lastObstacleTime = 0;
  let gameOver = false;
  const obstacles = [];

  // ----- player -----
  const player = {
    x: 80,
    y: GROUND_Y - PLAYER_SIZE,
    w: PLAYER_SIZE,
    h: PLAYER_SIZE,
    vy: 0,
    jumping: false,
    sliding: false,
    slideTimer: 0,
    update() {
      // apply gravity
      if (this.y + this.h < GROUND_Y) {
        this.vy += GRAVITY;
        this.y += this.vy;
        this.jumping = true;
        if (this.y + this.h > GROUND_Y) {
          this.y = GROUND_Y - this.h;
          this.vy = 0;
          this.jumping = false;
        }
      }
      // slide handling
      if (this.sliding) {
        this.slideTimer -= delta;
        if (this.slideTimer <= 0) {
          this.sliding = false;
          this.h = PLAYER_SIZE; // restore height
          this.y = GROUND_Y - this.h;
        }
      }
    },
    draw() {
      ctx.fillStyle = '#0a84ff';
      ctx.fillRect(this.x, this.y, this.w, this.h);
    },
    jump() {
      if (!this.jumping && !this.sliding) {
        this.vy = JUMP_VELOCITY;
        this.jumping = true;
      }
    },
    slide() {
      if (!this.jumping && !this.sliding) {
        this.sliding = true;
        this.slideTimer = SLIDE_TIME;
        this.h = PLAYER_SIZE / 2; // half height when sliding
        this.y = GROUND_Y - this.h;
      }
    }
  };

  // ----- obstacle helper -----
  function spawnObstacle() {
    const height = 30 + Math.random() * 60; // variable height
    const width = 20 + Math.random() * 30;
    obstacles.push({
      x: WIDTH,
      y: GROUND_Y - height,
      w: width,
      h: height
    });
  }

  // ----- input -----
  window.addEventListener('keydown', e => {
    if (gameOver) return;
    if (e.key === 'ArrowUp') player.jump();
    else if (e.key === 'ArrowDown') player.slide();
  });

  // ----- main loop -----
  let lastTime = performance.now();
  let delta = 0;
  function loop(now) {
    delta = now - lastTime;
    lastTime = now;
    if (!gameOver) {
      update(delta);
      render();
      requestAnimationFrame(loop);
    }
  }

  function update(dt) {
    // spawn obstacles
    if (now - lastObstacleTime > OBSTACLE_FREQ) {
      spawnObstacle();
      lastObstacleTime = now;
    }
    // update player
    player.update();
    // move obstacles
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const obs = obstacles[i];
      obs.x -= OBSTACLE_SPEED;
      // collision
      if (rectIntersect(player, obs)) {
        gameOver = true;
      }
      // remove off‑screen
      if (obs.x + obs.w < 0) {
        obstacles.splice(i, 1);
        score += 1; // reward for passing
      }
    }
  }

  function render() {
    // clear background
    ctx.fillStyle = '#f0f0f0';
    ctx.fillRect(0, 0, WIDTH, HEIGHT);
    // draw ground
    ctx.fillStyle = '#444';
    ctx.fillRect(0, GROUND_Y, WIDTH, HEIGHT - GROUND_Y);
    // draw player
    player.draw();
    // draw obstacles
    ctx.fillStyle = '#ff3b30';
    obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));
    // draw score
    ctx.fillStyle = '#000';
    ctx.font = '20px sans-serif';
    ctx.fillText(`Score: ${score}`, 10, 30);
    // game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, WIDTH, HEIGHT);
      ctx.fillStyle = '#fff';
      ctx.font = '36px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', WIDTH / 2, HEIGHT / 2);
      ctx.font = '24px sans-serif';
      ctx.fillText(`Final Score: ${score}`, WIDTH / 2, HEIGHT / 2 + 40);
    }
  }

  function rectIntersect(a, b) {
    return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
  }

  // start loop
  requestAnimationFrame(loop);
})();
